<?php
if(wp_get_environment_type()!=='local'||home_url()!=='http://127.0.0.1:8877')WP_CLI::error('Isolated local installation required.');
$results=array();$owned=array();$locks=array();$ips=array();$original_user=get_current_user_id();$options=array();foreach(array('ppt_enquiry_email','ppt_enquiries_enabled','ppt_exclude_demo_indexing')as $key)$options[$key]=get_option($key,null);
$token=wp_generate_uuid4();$email='cx-'.$token.'@example.test';$mail=array();$mail_fail=false;
$check=function($name,$pass,$detail='')use(&$results){$results[]=array('test'=>$name,'pass'=>(bool)$pass,'detail'=>$detail);};
$capture=function($pre,$attrs)use(&$mail,&$mail_fail){$mail[]=$attrs;return !$mail_fail;};add_filter('pre_wp_mail',$capture,50,2);
$ticket=function(){$issued=time()-2;$id=wp_generate_password(32,false,false);return $issued.'.'.$id.'.'.hash_hmac('sha256',$issued.'.'.$id,wp_salt('nonce'));};
$input=function($category='General')use($email,$ticket){return array('ppt_enquiry_nonce'=>wp_create_nonce('ppt_enquiry'),'ticket'=>$ticket(),'name'=>'CX Test','email'=>$email,'organisation'=>'Test organisation','category'=>$category,'message'=>'A controlled local enquiry for pathway verification.','consent'=>'1','context'=>'0');};
$submit=function($data,$ip=null)use(&$owned,&$locks,&$ips,$token){$ip=$ip?:$token.'-'.count($ips);$ips[]=$ip;$locks[]='ppt_enq_lock_'.hash_hmac('sha256',wp_json_encode(array(strtolower($data['email']??''),$data['category']??'',$data['message']??'',$data['organisation']??'',$data['context']??'')),wp_salt());$r=ppt_process_enquiry($data,$ip);if(!empty($r['id']))$owned[]=$r['id'];return $r;};
try{
 update_option('ppt_enquiry_email','captured@example.test');update_option('ppt_enquiries_enabled',1);wp_set_current_user(0);
 foreach(array('Publishing','Research','Partnership','Training','Learning','Editorial','General')as $category){$r=$submit($input($category));$id=$r['id']??0;$check('Enquiry saved and classified: '.$category,!empty($r['ok'])&&get_post_status($id)==='private'&&get_post_meta($id,'_ppt_category',true)===$category&&get_post_meta($id,'_ppt_notification',true)==='accepted_by_mail_transport');}
 $first=$input('Research');$before=count($mail);$r=$submit($first);$check('Duplicate retry uses existing record and sends no second notification',$r['ok']&&!empty($r['duplicate'])&&count($mail)===$before);
 foreach(array('name'=>'','email'=>'not-an-email','category'=>'Unknown','message'=>'short','consent'=>'','ppt_enquiry_nonce'=>'bad','ticket'=>'fake','website'=>'spam')as $field=>$value){$v=$input();$v[$field]=$value;$r=$submit($v);$check('Server rejects invalid '.$field,empty($r['ok'])&&!empty($r['errors'])&&$r['values']['name']===$v['name']);}
 $mail_fail=true;$v=$input();$v['message']='This unique message tests failed notifications with durable storage.';$r=$submit($v);$check('Mail failure retains a private staff record and truthful acceptance',$r['ok']&&get_post_meta($r['id'],'_ppt_notification',true)==='failed');$mail_fail=false;
 $check('Staff notification only uses configured recipient',count(array_filter($mail,function($m){return $m['to']!==array('captured@example.test')&&$m['to']!=='captured@example.test';}))===0);
 $fail_insert=function($empty,$post){return ($post['post_type']??'')==='ppt_enquiry_record'?true:$empty;};add_filter('wp_insert_post_empty_content',$fail_insert,10,2);$v=$input();$v['message']='This unique enquiry exercises a storage failure without a success claim.';$r=$submit($v);remove_filter('wp_insert_post_empty_content',$fail_insert);$check('Database insertion failure never claims success',empty($r['ok'])&&isset($r['errors']['form']));$r=$submit($v);$check('Storage failure can be retried successfully',$r['ok']);
 $ip=$token.'-limited';set_transient('ppt_enq_rate_'.hash_hmac('sha256',$ip,wp_salt()),12,900);$r=$submit($input(),$ip);$check('Rate limit retains the entered data',empty($r['ok'])&&strpos($r['errors']['form'],'15 minutes')!==false&&$r['values']['email']===$email);
 update_option('ppt_enquiries_enabled',0);$r=$submit($input());$check('Disabled service rejects direct submission',!$r['ok']);$check('Disabled UI does not offer a fake form',strpos(ppt_enquiry(),'<form')===false);update_option('ppt_enquiries_enabled',1);
 $obj=get_post_type_object('ppt_enquiry_record');$check('Enquiries excluded from public routing REST and search',!$obj->public&&!$obj->publicly_queryable&&!$obj->show_in_rest&&$obj->exclude_from_search);
 $check('Anonymous visitor cannot read enquiries',!current_user_can('read_post',$owned[0]));wp_set_current_user(1);$check('Authorised administrator can review enquiries',current_user_can('read_post',$owned[0])&&current_user_can('manage_ppt_enquiries'));
 $post=get_post($owned[0]);wp_update_post(array('ID'=>$post->ID,'post_status'=>'publish'));$check('An enquiry cannot accidentally be made public',get_post_status($post->ID)==='private');wp_trash_post($post->ID);$check('Staff can trash an enquiry',get_post_status($post->ID)==='trash');wp_untrash_post($post->ID);
 $exporters=apply_filters('wp_privacy_personal_data_exporters',array());$export=call_user_func($exporters['ppt-enquiries']['callback'],$email,1);$check('Native privacy export contains only the requested enquiries',count($export['data'])>=7&&$export['done']);
 $p=get_page_by_path('work-with-us');$content=$p->post_content;wp_update_post(array('ID'=>$p->ID,'post_content'=>$content."\n<!-- Editorial preservation sentinel -->"));$upgrade=ppt_upgrade_customer_experience(true);$check('Upgrade preserves later editorial changes',get_post($p->ID)->post_content===$content."\n<!-- Editorial preservation sentinel -->");wp_update_post(array('ID'=>$p->ID,'post_content'=>$content));
 $op=wp_insert_post(array('post_type'=>'ppt_training','post_title'=>'CX test opportunity','post_status'=>'publish'));$owned[]=$op;
 $check('Undated offering has honest interest flow',ppt_opportunity_state($op)==='Dates to be confirmed'&&strpos(ppt_opportunity_action($op),'enquiry=Learning')!==false);
 update_post_meta($op,'_ppt_training_start_date','2000-01-01');$check('Past session has no booking promise',ppt_opportunity_state($op)==='This session has ended'&&strpos(ppt_opportunity_action($op),'Ask about future')!==false);
 update_post_meta($op,'_ppt_demo_content',1);$check('Demo offering cannot promise enrollment',strpos(ppt_opportunity_state($op),'Demonstration')===0);
 $check('Native page is made of editable blocks',has_blocks($content)&&count(parse_blocks($content))>0&&strpos($content,'ppt-pathway')!==false);
 $erasers=apply_filters('wp_privacy_personal_data_erasers',array());$erased=call_user_func($erasers['ppt-enquiries']['callback'],$email,1);$check('Verified privacy-request eraser removes owned enquiry records',$erased['items_removed']&&!$erased['items_retained']);
}finally{foreach(array_unique($owned)as $id)if(get_post($id))wp_delete_post($id,true);foreach(array_unique($locks)as $key)delete_option($key);foreach(array_unique($ips)as $ip)delete_transient('ppt_enq_rate_'.hash_hmac('sha256',$ip,wp_salt()));foreach($options as $key=>$value){if($value===null)delete_option($key);else update_option($key,$value);}remove_filter('pre_wp_mail',$capture,50);wp_set_current_user($original_user);}
file_put_contents(dirname(ABSPATH,3).'/runtime/cx/enquiry-results.json',wp_json_encode($results,JSON_PRETTY_PRINT));echo wp_json_encode(array('count'=>count($results),'failures'=>array_values(array_filter($results,function($r){return !$r['pass'];}))));if(array_filter($results,function($r){return !$r['pass'];}))WP_CLI::halt(1);
